const i=t=>{const a=t.trim();if(!a)return[];const e=[];return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a)||e.push("Not a valid email format"),e},n=t=>{if(!t)return[];const a=[];return t.length<6&&a.push("Password must be at least 6 characters"),a},o=t=>{if(!t)return[];const a=[];return(/^\d{6}$/.test(t)??/^\d{9}$/.test(t))||a.push("Invalid pin"),a};export{i as validateEmail,n as validatePassword,o as validatePin};
